<?php
namespace App\Http\Controllers;
use App\Models\{TimetablePlan as Plan,TimetableOptimisationRun as Run};
use App\Support\{PortalActions,CentrePlanning,TimetableOptimiser as O};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class TimetableOptimiserController extends Controller {
 private function actor(Request $r){$u=PortalActions::actor($r->user());abort_unless(CentrePlanning::allowed($u),403);return $u;}
 private function page(string $view,array $data=[]){return response()->view('optimiser.'.$view,$data)->header('Cache-Control','private, no-store')->header('Referrer-Policy','no-referrer');}
 private function input(Request $r):array{return $r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d','plans'=>'required|array|min:1|max:8','plans.*'=>'required|uuid|distinct']);}
 public function index(Request $r){$u=$this->actor($r);$d=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d']);$from=$d['from']??today()->toDateString();$to=$d['to']??today()->addDays(27)->toDateString();O::range($from,$to);$plans=Plan::where('state','Published')->whereIn('id',\App\Models\TimetablePlanEntry::whereDate('work_date','>=',$from)->whereDate('work_date','<=',$to)->select('plan_id'))->orderBy('id')->limit(201)->get();$more=$plans->count()>200;$items=[];
  foreach($plans->take(200)as$p){try{$s=O::eligible($u,$p,$from,$to);$items[]=['id'=>$p->id,'title'=>$s['data']['args']['title'],'kind'=>$s['data']['args']['kind'],'date'=>$s['data']['args']['date'],'start'=>$s['data']['args']['start'],'end'=>$s['data']['args']['end'],'occurrences'=>count($s['data']['rows']),'eligible'=>true,'reason'=>null];}catch(\Throwable){$items[]=['id'=>$p->id,'title'=>'Plan held for its original workflow','eligible'=>false,'reason'=>'Changed, protected, partly delivered, linked, outside this period or unsupported source. Open the original plan to investigate.'];}}
  $runs=Run::where('created_by',$u->id)->orderByDesc('created_at')->paginate(10,['*'],'runs_page')->withQueryString();return $this->page('index',compact('from','to','items','more','runs'));
 }
 public function preview(Request $r){$this->actor($r);$d=$this->input($r);$preview=O::preview($r->user(),$d['plans'],$d['from'],$d['to']);$token=(string)Str::uuid();return $this->page('preview',compact('preview','token'));}
 public function prepare(Request $r){$this->actor($r);$d=$this->input($r);$extra=$r->validate(['source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','request_token'=>'required|uuid','reason'=>'required|string|min:5|max:1000','confirmed'=>'accepted']);$run=O::prepare($r->user(),(int)$r->session()->get('auth_version'),$d['plans'],$d['from'],$d['to'],$extra['source_hash'],$extra['request_token'],$extra['reason']);return to_route('optimiser.show',$run)->with('status','Proposal saved for your final check. Nothing has moved.');}
 public function show(Request $r,Run $run){$u=$this->actor($r);abort_unless($run->created_by===$u->id,404);abort_unless(O::intact($run),409,'Optimisation proof needs investigation.');return $this->page('show',['run'=>$run,'preview'=>$run->details['preview']]);}
 public function apply(Request $r,Run $run){$this->actor($r);$d=$r->validate(['version'=>'required|integer|in:1','details_hash'=>'required|regex:/^[a-f0-9]{64}$/D','warnings_accepted'=>'nullable|boolean','confirmed'=>'accepted','arrangements_checked'=>'accepted']);O::apply($r->user(),(int)$r->session()->get('auth_version'),$run,(int)$d['version'],$d['details_hash'],(bool)($d['warnings_accepted']??false));return to_route('optimiser.show',$run)->with('status','Reviewed time changes applied together. Original history retained; no register, attendance, OTJ or external message was created.');}
 public function cancel(Request $r,Run $run){$this->actor($r);$d=$r->validate(['version'=>'required|integer|in:1','details_hash'=>'required|regex:/^[a-f0-9]{64}$/D','confirmed'=>'accepted']);O::cancel($r->user(),(int)$r->session()->get('auth_version'),$run,(int)$d['version'],$d['details_hash']);return to_route('optimiser.show',$run)->with('status','Proposal cancelled. Nothing moved.');}
}
